// Skipped rules: [C3.S1: Not chosen initially because changing `BoundaryPM` to `&mut`/slice parameters would require caller analysis across recursive and external call sites; body-local III④ + C3 hoists can address the concrete hits without cross-function rewrite.]
unsafe fn BoundaryPM(
    mut lists: *mut [*mut Node; 2],
    mut leaves: *mut Node,
    mut numsymbols: c_int,
    mut pool: *mut NodePool,
    mut index: c_int,
) {
    // SAFETY: `lists` is indexed by `index` and, on the nonzero path, `index - 1`;
    // the algorithm/caller guarantees those entries exist, `lists` is non-null, and
    // no other references to this region are live while this body mutates through it.
    let lists_view = unsafe { ::core::slice::from_raw_parts_mut(lists, index as usize + 1) };
    // SAFETY: `leaves` is accessed at `lastcount`, where `lastcount < numsymbols` on every
    // path that reads it; the caller provides a non-null buffer of at least `numsymbols`
    // `Node`s, and no other references to the same region are live across this reborrow.
    let leaves_view = unsafe { ::core::slice::from_raw_parts(leaves, numsymbols as usize) };

    let current = &mut lists_view[index as usize];
    let old_last = current[1];
    let lastcount: c_int = (*old_last).count;
    if index == 0 as c_int && lastcount >= numsymbols {
        return;
    }

    let fresh4 = (*pool).next;
    (*pool).next = (*pool).next.offset(1);
    let newchain: *mut Node = fresh4;
    let oldchain: *mut Node = old_last;

    current[0] = oldchain;
    current[1] = newchain;

    if index == 0 as c_int {
        let leaf = &leaves_view[lastcount as usize];
        InitNode(
            leaf.weight,
            lastcount + 1 as c_int,
            ::core::ptr::null_mut::<Node>(),
            newchain,
        );
    } else {
        let prev = &lists_view[(index - 1 as c_int) as usize];
        let prev0 = prev[0];
        let prev1 = prev[1];
        let sum: size_t = (*prev0).weight.wrapping_add((*prev1).weight);

        if lastcount < numsymbols && sum > leaves_view[lastcount as usize].weight {
            let leaf = &leaves_view[lastcount as usize];
            InitNode(
                leaf.weight,
                lastcount + 1 as c_int,
                (*oldchain).tail,
                newchain,
            );
        } else {
            InitNode(sum, lastcount, prev1, newchain);
            BoundaryPM(lists, leaves, numsymbols, pool, index - 1 as c_int);
            BoundaryPM(lists, leaves, numsymbols, pool, index - 1 as c_int);
        }
    };
}

